"""parche-91: LEER UN TEXTO Y APRENDERLO. Tu autoexamen subio a 129/130 = 99,2 % con el parche-90 (solo falla "¿Qué es lo que compra Irene?" con un objeto plural).
Ahora el objetivo: escribes un texto en lenguaje natural (p. ej. sobre el sistema solar) y el modelo lo asimila para contestar despues.

  python -m scripts.leer_texto data/textos/sistema_solar.txt            (aprende y guarda en memory/lcm_memory.json, la misma memoria de scripts.think)
  python -m scripts.leer_texto mi_texto.txt --prueba                    (lee y mide, sin guardar)

Prepara el texto (quita parentesis, conectores "Además,/Sin embargo,", separa por ";", ignora titulos y lineas con #), lo pasa frase a frase por la
conversacion real (escuela, tema del discurso, correcciones) y se AUTOEXAMINA: por cada sujeto aprendido pregunta "¿Qué sabes de X?" y comprueba que
salen sus datos. Escribe reports/lectura.txt con: frases aprendidas / no entendidas, datos que no se recuerdan y todo lo aprendido.
Incluye un texto de ejemplo (data/textos/sistema_solar.txt). Es una herramienta nueva: no cambia el comportamiento del dialogo ni de los examenes.
IMPORTANTE para el siguiente paso: pon tu texto en data/textos/ , ejecuta el comando y subeme reports/lectura.txt (o el paquete): las frases NO ENTENDIDAS
se agrupan por familia (aposiciones, "tiene N cosas", superlativos...) y las arreglo por familias, como con el autoexamen.
Criterio: los 4 tests nuevos pasan y nada baja. Uso: python -m scripts.ciclo parche-91.py"""
import datetime, py_compile, shutil, sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
ALL_EDITS = []
NEW_FILES = {'src/language/ingesta.py': '"""Ingesta de TEXTOS (parche-91): lee un texto en lenguaje natural (p. ej. sobre el sistema solar), lo prepara frase a frase y lo pasa por la conversacion\nreal (la misma que usas en scripts.think: escuela, discurso con tema, correcciones, memoria). Despues se AUTOEXAMINA: por cada sujeto aprendido pregunta\n"¿Qué sabes de X?" y comprueba que sus datos salen en la respuesta. Devuelve un informe de lo aprendido / no entendido / recordado.\nNo hay LLM: si una frase no se entiende, se dice cual es y por que familia fallan (para arreglarlas por familias en el siguiente parche)."""\nimport re\nfrom typing import Dict, List, Tuple\n\nfrom .lexicon import norm\n\nCONECTORES = r"(?:adem[aá]s|asimismo|por otro lado|sin embargo|por eso|por ello|as[ií]|por lo tanto|en resumen|en consecuencia|adem[aá]s de eso|de hecho|entonces|igualmente|tambi[eé]n)"\n\n\ndef limpiar(frase: str) -> str:\n    f = re.sub(r"\\([^)]*\\)", " ", frase)                                  # (aclaraciones entre parentesis)\n    f = re.sub(r"\\[[^\\]]*\\]|\\bpag\\.\\s*\\d+", " ", f)\n    f = re.sub(r"\\s*[—–]\\s*[^—–]*?\\s*[—–]\\s*", ", ", f)                  # incisos entre rayas\n    f = re.sub(r"^\\s*" + CONECTORES + r"\\s*,?\\s+", "", f, flags=re.I)      # "Además, ..." -> "..."\n    f = re.sub(r"\\s+([.,;:!?])", r"\\1", re.sub(r"\\s+", " ", f)).strip(" ,;")\n    if f and f[0].islower():\n        f = f[0].upper() + f[1:]\n    return f\n\n\ndef preparar(texto: str) -> Tuple[List[str], List[str]]:\n    """-> (frases, titulos_ignorados). Una linea corta sin punto final es un titulo; \'#\' son comentarios."""\n    frases, titulos = [], []\n    for linea in texto.splitlines():\n        linea = linea.strip()\n        if not linea or linea.startswith("#"):\n            continue\n        if not re.search(r"[.!?:]$", linea) and len(linea.split()) <= 6:\n            titulos.append(linea)\n            continue\n        for trozo in re.split(r"(?<=[.!?])\\s+", linea):\n            for parte in re.split(r";\\s+", trozo):                         # "A es B; C es D." -> dos frases\n                f = limpiar(parte)\n                if len(f.split()) >= 2:\n                    frases.append(f if re.search(r"[.!?]$", f) else f + ".")\n    return frases, titulos\n\n\ndef clasificar(respuesta: str) -> str:\n    r = norm(respuesta or "")\n    if "no he entendido" in r or "puedes decirlo" in r or "frase mas simple" in r:\n        return "no_entendida"\n    if "entendido:" in r:\n        return "aprendida"\n    return "otra"\n\n\ndef leer(conv, mem, frases: List[str]) -> Dict:\n    """Pasa las frases por la conversacion. Devuelve {aprendidas, no_entendidas, otras, hechos_nuevos}."""\n    rep = {"aprendidas": [], "no_entendidas": [], "otras": [], "hechos_nuevos": []}\n    for f in frases:\n        antes = len(mem.facts)\n        resp = conv.say(f)\n        if getattr(conv.d, "pending", None):                              # en lectura por lotes no se puede contestar a preguntas de aclaracion\n            conv.d.pending = None\n            rep["otras"].append((f, "pregunta de aclaracion (conflicto con lo que ya sabia): " + resp[:120]))\n        c = clasificar(resp)\n        nuevos = [x for x in mem.facts[antes:] if not x.get("neg")]\n        rep["hechos_nuevos"] += nuevos\n        if c == "aprendida":\n            rep["aprendidas"].append((f, resp))\n        elif c == "no_entendida":\n            rep["no_entendidas"].append((f, resp))\n        else:\n            rep["otras"].append((f, resp))\n    return rep\n\n\ndef comprobar(conv, mem, hechos: List[dict]) -> Tuple[int, int, List[Tuple[str, str, str]]]:\n    """Autoexamen de retencion: por sujeto, \'¿Qué sabes de X?\' debe nombrar cada objeto aprendido. -> (ok, total, fallos[(sujeto, objeto, respuesta)])"""\n    por: Dict[str, List[str]] = {}\n    for h in hechos:\n        por.setdefault(h["s"], [])\n        if h["o"] not in por[h["s"]]:\n            por[h["s"]].append(h["o"])\n    ok = total = 0\n    fallos = []\n    for s, objs in por.items():\n        disp = mem.display.get(s, s.lower())\n        resp = norm(conv.say(f"¿Qué sabes de {disp}?"))\n        for o in objs:\n            total += 1\n            od = norm(mem.display.get(o, o.lower()))\n            if od and od in resp:\n                ok += 1\n            else:\n                fallos.append((disp, od, resp[:100]))\n    return ok, total, fallos\n\n\ndef informe(rep: Dict, titulos: List[str], chk: Tuple[int, int, list]) -> str:\n    a, n_, o = len(rep["aprendidas"]), len(rep["no_entendidas"]), len(rep["otras"])\n    tot = a + n_ + o\n    L = [f"LECTURA: {tot} frases -> {a} aprendidas, {n_} no entendidas, {o} otras  ({a / max(tot, 1):.0%} entendido). Hechos nuevos: {len(rep[\'hechos_nuevos\'])}."]\n    if titulos:\n        L.append("Títulos ignorados: " + " | ".join(titulos))\n    ok, total, fallos = chk\n    L.append(f"RETENCIÓN (¿Qué sabes de X?): {ok}/{total} = {ok / max(total, 1):.0%}")\n    if rep["no_entendidas"]:\n        L.append("\\nFRASES NO ENTENDIDAS:")\n        L += [f"  - {f}" for f, _ in rep["no_entendidas"]]\n    if rep["otras"]:\n        L.append("\\nOTRAS RESPUESTAS:")\n        L += [f"  - {f}  ->  {r[:110]}" for f, r in rep["otras"]]\n    if fallos:\n        L.append("\\nDATOS APRENDIDOS QUE NO SALEN AL PREGUNTAR:")\n        L += [f"  - {s}: falta «{o}»  (respuesta: {r!r})" for s, o, r in fallos]\n    L.append("\\nLO APRENDIDO:")\n    seen = set()\n    for h in rep["hechos_nuevos"]:\n        k = (h["s"], h["p"], h["o"])\n        if k not in seen:\n            seen.add(k)\n            L.append(f"  {h[\'s\']} {h[\'p\']} {h[\'o\']}")\n    return "\\n".join(L)\n', 'scripts/leer_texto.py': '"""Lee un texto en lenguaje natural y lo aprende (parche-91).   python -m scripts.leer_texto data/textos/sistema_solar.txt [--prueba] [--memoria RUTA]\nUsa la misma memoria que scripts.think (memory/lcm_memory.json), asi que despues puedes preguntarle en scripts.think.  --prueba: no guarda nada.\nEscribe reports/lectura.txt (lo aprendido, lo no entendido, y un autoexamen de retencion)."""\nimport argparse\nimport os\nimport sys\nfrom datetime import date\n\nimport torch\n\nfrom src.language.dialogue import Conversation\nfrom src.language.ingesta import comprobar, informe, leer, preparar\nfrom src.language.qa import QA\nfrom src.language.school_parser import SchoolParser\nfrom src.language.ud import load_school\nfrom src.memory.store import MemoryStore\nfrom src.reasoning.lessons import deduce_all\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("archivo")\n    ap.add_argument("--prueba", action="store_true", help="no guardar en la memoria")\n    ap.add_argument("--memoria", default="memory/lcm_memory.json")\n    a = ap.parse_args()\n    if not os.path.exists(a.archivo):\n        sys.exit(f"No encuentro {a.archivo}")\n    device = "cuda" if torch.cuda.is_available() else ("mps" if torch.backends.mps.is_available() else "cpu")\n    try:\n        from src.language.school_learn import load_overrides\n        ov = load_overrides()\n    except Exception:                                                     # noqa\n        ov = None\n    model, scripts = load_school(device=device)\n    parser = SchoolParser(model, device, scripts, ov) if ov is not None else SchoolParser(model, device, scripts)\n    mem = MemoryStore(a.memoria)\n    mem.today = parser.today = date.today()\n    from src.language.semilla import load_seed\n    load_seed(mem, parser)\n    conv = Conversation(mem, parser, lambda m, p: QA(m, p.parse, lambda facts: deduce_all(facts, m.active_lessons())))\n    frases, titulos = preparar(open(a.archivo, encoding="utf-8").read())\n    rep = leer(conv, mem, frases)\n    chk = comprobar(conv, mem, rep["hechos_nuevos"])\n    text = informe(rep, titulos, chk)\n    os.makedirs("reports", exist_ok=True)\n    open("reports/lectura.txt", "w", encoding="utf-8").write(text)\n    print(text)\n    if a.prueba:\n        print("\\n[--prueba: memoria NO guardada]")\n    else:\n        mem.save()\n        print(f"\\n[Memoria guardada en {a.memoria}: {mem.summary()}. Ahora puedes preguntarle en python -m scripts.think]")\n\n\nif __name__ == "__main__":\n    main()\n', 'tests/test_parche91.py': '"""parche-91: preparacion de textos y clasificacion de lectura."""\nfrom src.language.ingesta import clasificar, comprobar, limpiar, preparar\n\n\ndef test_preparar_texto():\n    txt = "# comentario\\nEl Sistema Solar\\nEl Sol es una estrella (la más cercana). Además, Marte es rojo; Venus es caliente.\\n"\n    frases, titulos = preparar(txt)\n    assert titulos == ["El Sistema Solar"]\n    assert frases == ["El Sol es una estrella.", "Marte es rojo.", "Venus es caliente."]\n\n\ndef test_limpiar_conectores_y_parentesis():\n    assert limpiar("Sin embargo, la Luna gira (despacio) alrededor de la Tierra.") == "La Luna gira alrededor de la Tierra."\n    assert limpiar("también tiene anillos.") == "Tiene anillos."\n\n\ndef test_clasificar():\n    assert clasificar("Entendido: MARTE SER ROJO.") == "aprendida"\n    assert clasificar("No he entendido «x». ¿Puedes decirlo con una frase más simple?") == "no_entendida"\n    assert clasificar("Vale.") == "otra"\n\n\nclass _Conv:\n    def say(self, q):\n        return "Marte es rojo y tiene dos lunas."\n\n\nclass _Mem:\n    display = {"MARTE": "Marte", "ROJO": "rojo", "LUNAS": "dos lunas"}\n\n\ndef test_comprobar_retencion():\n    hechos = [{"s": "MARTE", "p": "SER", "o": "ROJO"}, {"s": "MARTE", "p": "TENER", "o": "LUNAS"}, {"s": "MARTE", "p": "SER", "o": "AZUL"}]\n    ok, total, fallos = comprobar(_Conv(), _Mem(), hechos)\n    assert (ok, total) == (2, 3) and fallos[0][1] == "azul"\n', 'data/textos/sistema_solar.txt': '# Ejemplo: sustituye este texto por el tuyo (lenguaje natural, frases completas).\nEl Sistema Solar\nEl Sol es una estrella. El Sol está en el centro del Sistema Solar. Los planetas giran alrededor del Sol.\nMercurio es el planeta más cercano al Sol. Venus es el segundo planeta. La Tierra es el tercer planeta y tiene una luna. La Luna gira alrededor de la Tierra.\nMarte es un planeta rojo. Marte tiene dos lunas. Júpiter es el planeta más grande. Júpiter es un gigante gaseoso. Saturno tiene anillos. Urano y Neptuno son planetas helados.\nPlutón es un planeta enano. Los asteroides son rocas pequeñas. Los cometas están hechos de hielo y polvo.\n'}

def main(root: Path = ROOT) -> int:
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    bk = root / ".parche_backups" / stamp
    texts, changed = {}, set()
    for rel, old, new, marca in ALL_EDITS:                              # comprobar TODO antes de escribir nada
        p = root / rel
        if not p.is_file():
            print(f"FALTA {rel}: no se toca nada."); return 1
        txt = texts[rel] if rel in texts else p.read_text(encoding="utf-8")
        if marca in txt:
            texts[rel] = txt; continue
        if txt.count(old) != 1:
            print(f"ERROR {rel}: un trozo a cambiar aparece {txt.count(old)} veces (debe ser 1): {old[:70]!r}. No se toca nada."); return 1
        texts[rel] = txt.replace(old, new); changed.add(rel)
    plan = [(root / rel, rel, texts[rel]) for rel in sorted(changed)]
    for rel, content in NEW_FILES.items():
        p = root / rel
        if not p.exists() or p.read_text(encoding="utf-8") != content:
            plan.append((p, rel, content))
    for p, rel, txt in plan:
        if p.exists():
            (bk / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, bk / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(txt, encoding="utf-8")
        if rel.endswith(".py"):
            py_compile.compile(str(p), doraise=True)
        print(f"  escrito {rel}")
    print(f"parche-91 instalado. Copias en {bk}" if plan else "parche-91: nada que hacer.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

